UserMessageSpillGuard _guard(
  ExecutionEnv env, {
  SpillsConfig config = const SpillsConfig(userThreshold: 1024),
  int budgetTokens = 4000,
  String? sessionId = 'sess-1',
  String Function(String text)? redact,
}) {
  return UserMessageSpillGuard(
