      );
      expect(
        const SpillsConfig(userFraction: 0.75).toYaml(),
        'spills:\n  userFraction: 0.75\n',
      );
      expect(
        const SpillsConfig(enabled: false).toYaml(),
        'spills:\n  enabled: false\n',
